pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        vm.assume(c != C(address(receiver)));

        uint256 initialBalance = address(c).balance;
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.sendTo.selector, receiver, amount));

        if (success) {
            assertTrue(address(c).balance == initialBalance - amount);
        } else {
            assertTrue(address(c).balance == initialBalance);
        }
    }
}

