pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);

        uint256 balanceBefore = address(c).balance;

        // Fund the contract so it has balance to send
        vm.deal(address(c), amount);

        bool reverted;
        try c.sendTo(receiver, amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balanceAfter = address(c).balance;

        // Either it reverted or the balance decreased by exactly amount
        assertTrue(reverted || balanceAfter == balanceBefore + amount - amount);
    }
}

